parameters.jsCode:
// Get the JSON string from the Gemini API response
// Gemini wraps the text inside candidates[0].content.parts[0].text
const geminiResponse = $input.first().json.candidates[0].content.parts[0].text;

// Parse the string into a real JSON object
let parsedData;
try {
  // Use a regex to strip markdown blocks if the model accidentally included them
  let cleanString = geminiResponse.replace(/```(?:json)?\n?/g, '').trim();
  parsedData = JSON.parse(cleanString);
} catch (error) {
  // If parsing fails, throw an error to flag it
  throw new Error(`Failed to parse Gemini JSON: ${error.message}`);
}

// Ensure the numerical fields are actually numbers for the math validation later
if (parsedData.amount_ht) parsedData.amount_ht = Number(parsedData.amount_ht);
if (parsedData.tva_amount) parsedData.tva_amount = Number(parsedData.tva_amount);
if (parsedData.amount_ttc) parsedData.amount_ttc = Number(parsedData.amount_ttc);

if (parsedData.items && Array.isArray(parsedData.items)) {
    parsedData.items.forEach(item => {
        if (item.quantity) item.quantity = Number(item.quantity);
        if (item.unit_price) item.unit_price = Number(item.unit_price);
        if (item.discount_percent) item.discount_percent = Number(item.discount_percent);
        if (item.total) item.total = Number(item.total);
    });
}

// Return the clean, parsed object as the new item
return parsedData;

// Loop through all items passed from the previous node
for (let item of $input.all()) {
  let invoice = item.json;
  let errors = []; // We will store any discrepancies here

  // 1. TRUTH CHECK: Ensure mandatory Moroccan Tax IDs exist
  if (!invoice.vendor_ice) errors.push("Missing Vendor ICE (Required for deduction).");
  if (!invoice.client_ice) errors.push("Missing Client ICE (Required for deduction).");
  if (!invoice.vendor_if) errors.push("Missing Vendor IF (Identifiant Fiscal).");

  // 2. MATH CHECK: Verify line item totals (HT) INCLUDING DISCOUNTS
  let calculated_ht = 0;

  if (invoice.items && Array.isArray(invoice.items)) {
    invoice.items.forEach((line, index) => {
      // Safely handle missing discounts
      let discount = line.discount_percent || 0; 

      // Math: (Qty * Unit Price HT) - Discount %
      let base_total = line.quantity * line.unit_price;
      let expected_line_total = base_total * (1 - (discount / 100));

      // Check if our math matches the printed Montant HT (allowing a 0.05 MAD margin for rounding)
      if (Math.abs(expected_line_total - line.total) > 0.05) {
        errors.push(`Line ${index + 1} math error: ${line.quantity} x ${line.unit_price} minus ${discount}% discount should be ${expected_line_total.toFixed(2)}, but invoice says ${line.total}.`);
      }

      // Add to our running Subtotal HT
      calculated_ht += line.total;
    });
  }

  // 3. MATH CHECK: Verify Subtotal HT matches the sum of the lines
  if (Math.abs(calculated_ht - invoice.amount_ht) > 0.05) {
    errors.push(`Amount HT mismatch. Items sum to ${calculated_ht.toFixed(2)}, but invoice states ${invoice.amount_ht}.`);
  }

  // 4. MATH CHECK: HT + TVA = TTC
  let calculated_ttc = invoice.amount_ht + invoice.tva_amount;
  if (Math.abs(calculated_ttc - invoice.amount_ttc) > 0.05) {
    errors.push(`Amount TTC mismatch. HT + TVA equals ${calculated_ttc.toFixed(2)}, but invoice states ${invoice.amount_ttc}.`);
  }

  // 5. ROUTING PREPARATION: Attach the validation results
  invoice.isValid = errors.length === 0;
  invoice.validation_errors = errors;
}

// Return the newly validated items
return $input.all();

// This node expects standard JSON input containing invoice details
// Make sure to run this AFTER your Math Validation node to ensure the data is perfect

const items = $input.all();
const xmlOutputs = [];

for (let item of items) {
  const invoice = item.json;

  // Skip invalid invoices if you haven't filtered them already
  if (invoice.isValid === false) {
    xmlOutputs.push({ json: { error: "Invoice failed validation", data: invoice } });
    continue;
  }

  // The UBL 2.1 standard requires these specific namespaces at the root
  let xml = `<?xml version="1.0" encoding="UTF-8"?>
<Invoice xmlns="urn:oasis:names:specification:ubl:schema:xsd:Invoice-2"
         xmlns:cac="urn:oasis:names:specification:ubl:schema:xsd:CommonAggregateComponents-2"
         xmlns:cbc="urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2">
`;

  // Basic invoice metadata
  xml += `  <cbc:UBLVersionID>2.1</cbc:UBLVersionID>
  <cbc:CustomizationID>urn:cen.eu:en16931:2017#compliant#urn:dgi.gov.ma:facturation:v1.0</cbc:CustomizationID>
  <cbc:ID>${invoice.invoice_number || 'UNKNOWN'}</cbc:ID>
  <cbc:IssueDate>${invoice.invoice_date || new Date().toISOString().split('T')[0]}</cbc:IssueDate>
  <cbc:InvoiceTypeCode>380</cbc:InvoiceTypeCode> <!-- 380 indicates a standard commercial invoice -->
  <cbc:DocumentCurrencyCode>MAD</cbc:DocumentCurrencyCode>
`;

  // cac:AccountingSupplierParty contains the Vendor details
  xml += `  <cac:AccountingSupplierParty>
    <cac:Party>
      <cac:PartyName>
        <cbc:Name>${invoice.vendor_name || 'Missing Vendor Name'}</cbc:Name>
      </cac:PartyName>
      <cac:PartyLegalEntity>
        <cbc:RegistrationName>${invoice.vendor_name || 'Missing Vendor Name'}</cbc:RegistrationName>
        <cbc:CompanyID schemeID="ICE">${invoice.vendor_ice || '000000000000000'}</cbc:CompanyID>
      </cac:PartyLegalEntity>
      <cac:PartyTaxScheme>
        <cbc:CompanyID schemeID="IF">${invoice.vendor_if || '0000000'}</cbc:CompanyID>
        <cac:TaxScheme>
          <cbc:ID>VAT</cbc:ID>
        </cac:TaxScheme>
      </cac:PartyTaxScheme>
    </cac:Party>
  </cac:AccountingSupplierParty>
`;

  // cac:AccountingCustomerParty contains the Buyer details
  xml += `  <cac:AccountingCustomerParty>
    <cac:Party>
      <cac:PartyName>
        <cbc:Name>${invoice.client_name || 'Missing Client Name'}</cbc:Name>
      </cac:PartyName>
      <cac:PartyLegalEntity>
        <cbc:RegistrationName>${invoice.client_name || 'Missing Client Name'}</cbc:RegistrationName>
        <cbc:CompanyID schemeID="ICE">${invoice.client_ice || '000000000000000'}</cbc:CompanyID>
      </cac:PartyLegalEntity>
    </cac:Party>
  </cac:AccountingCustomerParty>
`;

  // Overall Tax calculations
  const tvaRate = invoice.tva_rate || 20; // Default to 20% if missing
  const tvaAmount = invoice.tva_amount || 0;
  const amountHt = invoice.amount_ht || 0;

  xml += `  <cac:TaxTotal>
    <cbc:TaxAmount currencyID="MAD">${tvaAmount.toFixed(2)}</cbc:TaxAmount>
    <cac:TaxSubtotal>
      <cbc:TaxableAmount currencyID="MAD">${amountHt.toFixed(2)}</cbc:TaxableAmount>
      <cbc:TaxAmount currencyID="MAD">${tvaAmount.toFixed(2)}</cbc:TaxAmount>
      <cac:TaxCategory>
        <cbc:ID>S</cbc:ID> <!-- Standard rate -->
        <cbc:Percent>${tvaRate}</cbc:Percent>
        <cac:TaxScheme>
          <cbc:ID>VAT</cbc:ID>
        </cac:TaxScheme>
      </cac:TaxCategory>
    </cac:TaxSubtotal>
  </cac:TaxTotal>
`;

  // The final required totals
  xml += `  <cac:LegalMonetaryTotal>
    <cbc:LineExtensionAmount currencyID="MAD">${amountHt.toFixed(2)}</cbc:LineExtensionAmount>
    <cbc:TaxExclusiveAmount currencyID="MAD">${amountHt.toFixed(2)}</cbc:TaxExclusiveAmount>
    <cbc:TaxInclusiveAmount currencyID="MAD">${(invoice.amount_ttc || 0).toFixed(2)}</cbc:TaxInclusiveAmount>
    <cbc:PayableAmount currencyID="MAD">${(invoice.amount_ttc || 0).toFixed(2)}</cbc:PayableAmount>
  </cac:LegalMonetaryTotal>
`;

  // Now add each individual product/service from the invoice array
  if (invoice.items && Array.isArray(invoice.items)) {
    invoice.items.forEach((line, index) => {
      let lineTotal = line.total || (line.quantity * line.unit_price);
      let discountPercent = parseFloat(line.discount_percent) || 0;

      xml += `  <cac:InvoiceLine>
    <cbc:ID>${index + 1}</cbc:ID>
    <cbc:InvoicedQuantity unitCode="EA">${line.quantity || 1}</cbc:InvoicedQuantity>
    <cbc:LineExtensionAmount currencyID="MAD">${lineTotal.toFixed(2)}</cbc:LineExtensionAmount>
`;

      // NEW: Inject AllowanceCharge for Discounts
      if (discountPercent > 0) {
        let baseAmount = line.quantity * line.unit_price;
        let discountAmount = baseAmount * (discountPercent / 100);
        xml += `    <cac:AllowanceCharge>
      <cbc:ChargeIndicator>false</cbc:ChargeIndicator> <!-- false means it is a discount, not a charge -->
      <cbc:MultiplierFactorNumeric>${discountPercent}</cbc:MultiplierFactorNumeric>
      <cbc:Amount currencyID="MAD">${discountAmount.toFixed(2)}</cbc:Amount>
      <cbc:BaseAmount currencyID="MAD">${baseAmount.toFixed(2)}</cbc:BaseAmount>
    </cac:AllowanceCharge>
`;
      }

      xml += `    <cac:Item>
      <cbc:Description>${line.description || 'Unknown Item'}</cbc:Description>
      <cbc:Name>${line.description || 'Unknown Item'}</cbc:Name>
    </cac:Item>
    <cac:Price>
      <cbc:PriceAmount currencyID="MAD">${(line.unit_price || 0).toFixed(2)}</cbc:PriceAmount>
    </cac:Price>
  </cac:InvoiceLine>
`;
    });
  }

  // Close the root Invoice tag
  xml += `</Invoice>`;

  // Output the XML string along with the original metadata
 // Output the EXACT shape the frontend expects
  xmlOutputs.push({
    json: {
      status: "Success",
      isValid: true,
      data: {
        vendor_name: invoice.vendor_name,
        vendor_ice: invoice.vendor_ice,
        client_name: invoice.client_name,
        client_ice: invoice.client_ice,
        amount_ttc: invoice.amount_ttc,
        items: invoice.items,
        ubl_xml: xml
      }
    }
  });

}

return xmlOutputs;
